insert into public.ejercicio (id,nombre_es,nombre_en,musculos_principales,musculos_secundarios,equipo,categoria,tipo_registro,imagenes,instrucciones,fuente,licencia) values
('Barbell_Bench_Press_-_Medium_Grip','Press de banca con barra','Barbell Bench Press - Medium Grip',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'barbell','strength','reps',ARRAY['Barbell_Bench_Press_-_Medium_Grip/0.jpg','Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[],ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.','After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Barbell_Hip_Thrust','Hip thrust con barra','Barbell Hip Thrust',ARRAY['glutes']::text[],ARRAY['calves','hamstrings']::text[],'barbell','powerlifting','reps',ARRAY['Barbell_Hip_Thrust/0.jpg','Barbell_Hip_Thrust/1.jpg']::text[],ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.','Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Bent-Arm_Dumbbell_Pullover','Pull over con mancuerna','Bent-Arm Dumbbell Pullover',ARRAY['chest']::text[],ARRAY['lats','shoulders','triceps']::text[],'dumbbell','strength','reps',ARRAY['Bent-Arm_Dumbbell_Pullover/0.jpg','Bent-Arm_Dumbbell_Pullover/1.jpg']::text[],ARRAY['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Close-Grip_Front_Lat_Pulldown','Jalón agarre cerrado','Close-Grip Front Lat Pulldown',ARRAY['lats']::text[],ARRAY['biceps','middle back','shoulders']::text[],'cable','strength','reps',ARRAY['Close-Grip_Front_Lat_Pulldown/0.jpg','Close-Grip_Front_Lat_Pulldown/1.jpg']::text[],ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','6. Repeat this motion for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Concentration_Curls','Curl concentrado (unilateral)','Concentration Curls',ARRAY['biceps']::text[],ARRAY['forearms']::text[],'dumbbell','strength','reps',ARRAY['Concentration_Curls/0.jpg','Concentration_Curls/1.jpg']::text[],ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Dead_Bug','Bicho muerto','Dead Bug',ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','tiempo',ARRAY['Dead_Bug/0.jpg','Dead_Bug/1.jpg']::text[],ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','Stay tight and return the working leg to the starting position.','Repeat on the opposite side, alternating until the set is complete.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Dumbbell_Alternate_Bicep_Curl','Curl alterno girando','Dumbbell Alternate Bicep Curl',ARRAY['biceps']::text[],ARRAY['forearms']::text[],'dumbbell','strength','reps',ARRAY['Dumbbell_Alternate_Bicep_Curl/0.jpg','Dumbbell_Alternate_Bicep_Curl/1.jpg']::text[],ARRAY['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Dumbbell_Flyes','Aperturas con mancuernas','Dumbbell Flyes',ARRAY['chest']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Dumbbell_Flyes/0.jpg','Dumbbell_Flyes/1.jpg']::text[],ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('EZ-Bar_Skullcrusher','Press francés con barra EZ','EZ-Bar Skullcrusher',ARRAY['triceps']::text[],ARRAY['forearms']::text[],'e-z curl bar','strength','reps',ARRAY['EZ-Bar_Skullcrusher/0.jpg','EZ-Bar_Skullcrusher/1.jpg']::text[],ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','Lift the bar back to the starting position by extending the elbow and exhaling.','Repeat.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Front_Dumbbell_Raise','Elevaciones frontales','Front Dumbbell Raise',ARRAY['shoulders']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Front_Dumbbell_Raise/0.jpg','Front_Dumbbell_Raise/1.jpg']::text[],ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.','Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.','Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Glute_Kickback','Patada de glúteo','Glute Kickback',ARRAY['glutes']::text[],ARRAY['hamstrings']::text[],'body only','strength','reps',ARRAY['Glute_Kickback/0.jpg','Glute_Kickback/1.jpg']::text[],ARRAY['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.','As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.','Go back to the initial position as you inhale and now repeat with the left leg.','Continue to alternate legs until all of the recommended repetitions have been performed.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Hammer_Curls','Curl martillo','Hammer Curls',ARRAY['biceps']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Hammer_Curls/0.jpg','Hammer_Curls/1.jpg']::text[],ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Hyperextensions_Back_Extensions','Hiperextensión','Hyperextensions (Back Extensions)',ARRAY['lower back']::text[],ARRAY['glutes','hamstrings']::text[],'other','strength','reps',ARRAY['Hyperextensions_Back_Extensions/0.jpg','Hyperextensions_Back_Extensions/1.jpg']::text[],ARRAY['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.','Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.','With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.','Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.','Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Incline_Dumbbell_Press','Press inclinado con mancuernas','Incline Dumbbell Press',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'dumbbell','strength','reps',ARRAY['Incline_Dumbbell_Press/0.jpg','Incline_Dumbbell_Press/1.jpg']::text[],ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.','Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.','Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('KK_Bear_Plank_Shoulder_Tap','Bear plank con toque de hombro',NULL,ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','tiempo','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Descanso','Día de descanso',NULL,'{}'::text[],'{}'::text[],NULL,'strength','check','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Jalon_Frente','Jalón a la frente',NULL,ARRAY['shoulders']::text[],'{}'::text[],'cable','strength','reps','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Plancha_Brazos_Alternos','Plancha con brazos alternos',NULL,ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','tiempo','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Plancha_Inversa_Elevacion_Piernas','Plancha inversa con elevación de piernas',NULL,ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','tiempo','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Press_Burro','Press de burro (tríceps)',NULL,ARRAY['triceps']::text[],'{}'::text[],NULL,'strength','reps','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Puente_Gluteo_Marcha','Puente de glúteo en marcha',NULL,ARRAY['glutes']::text[],'{}'::text[],'body only','strength','tiempo','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('KK_Puente_Gluteo_Marcha_Pierna_Estirada','Puente de glúteo en marcha con pierna estirada',NULL,ARRAY['glutes']::text[],'{}'::text[],'body only','strength','tiempo','{}'::text[],'{}'::text[],'Kokorosd',NULL),
('Leg_Press','Prensa de piernas','Leg Press',ARRAY['quadriceps']::text[],ARRAY['calves','glutes','hamstrings']::text[],'machine','strength','reps',ARRAY['Leg_Press/0.jpg','Leg_Press/1.jpg']::text[],ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench','Curl de muñeca (antebrazo)','Palms-Up Dumbbell Wrist Curl Over A Bench',ARRAY['forearms']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg','Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[],ARRAY['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Plank','Plancha','Plank',ARRAY['abdominals']::text[],'{}'::text[],'body only','strength','tiempo',ARRAY['Plank/0.jpg','Plank/1.jpg']::text[],ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.','Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Pushups','Flexiones','Pushups',ARRAY['chest']::text[],ARRAY['shoulders','triceps']::text[],'body only','strength','reps',ARRAY['Pushups/0.jpg','Pushups/1.jpg']::text[],ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Reverse_Flyes','Vuelos traseros','Reverse Flyes',ARRAY['shoulders']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Reverse_Flyes/0.jpg','Reverse_Flyes/1.jpg']::text[],ARRAY['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).','Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.','Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.','The arms should be elevated until they are parallel to the floor.','Feel the contraction and slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Romanian_Deadlift','Peso muerto rumano','Romanian Deadlift',ARRAY['hamstrings']::text[],ARRAY['calves','glutes','lower back']::text[],'barbell','strength','reps',ARRAY['Romanian_Deadlift/0.jpg','Romanian_Deadlift/1.jpg']::text[],ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.','Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.','Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.','Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Russian_Twist','Abdominales rusos','Russian Twist',ARRAY['abdominals']::text[],ARRAY['lower back']::text[],'body only','strength','reps',ARRAY['Russian_Twist/0.jpg','Russian_Twist/1.jpg']::text[],ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','Twist your torso to the right side until your arms are parallel with the floor while breathing out.','Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Seated_Cable_Rows','Remo sentado en polea','Seated Cable Rows',ARRAY['middle back']::text[],ARRAY['biceps','lats','shoulders']::text[],'cable','strength','reps',ARRAY['Seated_Cable_Rows/0.jpg','Seated_Cable_Rows/1.jpg']::text[],ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Seated_Leg_Curl','Curl femoral sentado','Seated Leg Curl',ARRAY['hamstrings']::text[],'{}'::text[],'machine','strength','reps',ARRAY['Seated_Leg_Curl/0.jpg','Seated_Leg_Curl/1.jpg']::text[],ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.','Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.','As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Side_Lateral_Raise','Elevaciones laterales','Side Lateral Raise',ARRAY['shoulders']::text[],'{}'::text[],'dumbbell','strength','reps',ARRAY['Side_Lateral_Raise/0.jpg','Side_Lateral_Raise/1.jpg']::text[],ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.','While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbells back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Standing_Leg_Curl','Curl femoral de pie','Standing Leg Curl',ARRAY['hamstrings']::text[],'{}'::text[],'machine','strength','reps',ARRAY['Standing_Leg_Curl/0.jpg','Standing_Leg_Curl/1.jpg']::text[],ARRAY['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.','Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.','As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.','As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.','Perform the same exercise now for the left leg.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Standing_Military_Press','Press militar de pie','Standing Military Press',ARRAY['shoulders']::text[],ARRAY['triceps']::text[],'barbell','strength','reps',ARRAY['Standing_Military_Press/0.jpg','Standing_Military_Press/1.jpg']::text[],ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.','Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.','Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the collarbone slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Stomach_Vacuum','Hipopresivo (vacío abdominal)','Stomach Vacuum',ARRAY['abdominals']::text[],'{}'::text[],'body only','stretching','tiempo',ARRAY['Stomach_Vacuum/0.jpg','Stomach_Vacuum/1.jpg']::text[],ARRAY['To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.','Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.','One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.','Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.','Repeat for the recommended amount of sets.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Superman','Bird dog / superman','Superman',ARRAY['lower back']::text[],ARRAY['glutes','hamstrings']::text[],'body only','stretching','tiempo',ARRAY['Superman/0.jpg','Superman/1.jpg']::text[],ARRAY['To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.','Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.','Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Thigh_Abductor','Abductor en máquina','Thigh Abductor',ARRAY['abductors']::text[],ARRAY['glutes']::text[],'machine','strength','reps',ARRAY['Thigh_Abductor/0.jpg','Thigh_Abductor/1.jpg']::text[],ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.','Slowly press against the machine with your legs to move them away from each other while exhaling.','Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Thigh_Adductor','Aductor en máquina','Thigh Adductor',ARRAY['adductors']::text[],ARRAY['glutes','hamstrings']::text[],'machine','strength','reps',ARRAY['Thigh_Adductor/0.jpg','Thigh_Adductor/1.jpg']::text[],ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.','Slowly press against the machine with your legs to move them towards each other while exhaling.','Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Triceps_Pushdown','Extensión de tríceps en polea','Triceps Pushdown',ARRAY['triceps']::text[],'{}'::text[],'cable','strength','reps',ARRAY['Triceps_Pushdown/0.jpg','Triceps_Pushdown/1.jpg']::text[],ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.','Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.','Repeat for the recommended amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Walking_Treadmill','Cinta (caminar inclinada)','Walking, Treadmill',ARRAY['quadriceps']::text[],ARRAY['calves','glutes','hamstrings']::text[],'machine','cardio','reps',ARRAY['Walking_Treadmill/0.jpg','Walking_Treadmill/1.jpg']::text[],ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.','Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Weighted_Sissy_Squat','Sentadilla sissy','Weighted Sissy Squat',ARRAY['quadriceps']::text[],ARRAY['calves','glutes','hamstrings']::text[],'barbell','strength','reps',ARRAY['Weighted_Sissy_Squat/0.jpg','Weighted_Sissy_Squat/1.jpg']::text[],ARRAY['Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.','As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.','After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.','Repeat for the recommended amount of times.']::text[],'Free Exercise DB','Unlicense (dominio público)'),
('Wide-Grip_Lat_Pulldown','Jalón agarre amplio','Wide-Grip Lat Pulldown',ARRAY['lats']::text[],ARRAY['biceps','middle back','shoulders']::text[],'cable','strength','reps',ARRAY['Wide-Grip_Lat_Pulldown/0.jpg','Wide-Grip_Lat_Pulldown/1.jpg']::text[],ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.','After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[],'Free Exercise DB','Unlicense (dominio público)')
